<style>
:root{--p:#0B7C8A;--on:#fff;--pl:color-mix(in srgb,var(--p) 16%,#fff);--pl2:color-mix(in srgb,var(--p) 7%,#fff);--bg:#F2F7F8;--b:#e6e8ef;--t:#161a2d;--m:#6b7285}
*{box-sizing:border-box}body{margin:0;font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--t);font-size:15px;line-height:1.45}
header.pt{background:#fff;border-bottom:1px solid var(--b)}
.w{max-width:980px;margin:0 auto;padding:0 20px}
.top{display:flex;justify-content:space-between;align-items:center;padding:14px 0;gap:12px;flex-wrap:wrap}
.top img{height:30px}.who{font-size:13px;color:var(--m);text-align:right}.who b{color:var(--t);display:block;font-size:14px}
.hero{padding:26px 0 8px}h1{margin:0 0 4px;font-size:24px}.sub{color:var(--m);font-size:14px}
.tabs{display:flex;gap:22px;border-bottom:1px solid var(--b);margin:18px 0 20px;overflow-x:auto;white-space:nowrap}
.tabs a{padding:10px 2px;color:var(--m);font-size:14px;text-decoration:none;border-bottom:2px solid transparent}
.tabs a.on{color:var(--p);border-color:var(--p);font-weight:600}
.card{background:#fff;border:1px solid var(--b);border-radius:14px;padding:18px 20px;margin-bottom:16px}
h2{font-size:16px;margin:0 0 12px}
.row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 0;border-top:1px solid #f0f1f5;flex-wrap:wrap}
.row:first-of-type{border-top:0}.ref{font-weight:600}.mut{color:var(--m);font-size:13px}
.badge{display:inline-block;padding:3px 10px;border-radius:99px;font-size:12px;font-weight:600}
.bl{background:#dbeafe;color:#1e40af}.gr{background:#d1fae5;color:#065f46}.ye{background:#fef3c7;color:#92400e}.rd{background:#fee2e2;color:#991b1b}.gy{background:#eef0f6;color:#4b5563}
.steps{display:flex;gap:4px;margin-top:8px;width:260px;max-width:100%}.steps i{height:6px;flex:1;border-radius:4px;background:#e6e8ef}.steps i.d{background:var(--p)}
.e-qualifie{background:#e0e7ff;color:#3730a3}.e-sourcing{background:#ede9fe;color:#5b21b6}.e-cotation{background:#fef3c7;color:#92400e}.e-commande{background:#dbeafe;color:#1e40af}.e-livraison{background:#ccfbf1;color:#115e59}.e-cloture{background:#e5e7eb;color:#374151}
.steps.s-qualifie i.d{background:#6366f1}.steps.s-sourcing i.d{background:#8b5cf6}.steps.s-cotation i.d{background:#f59e0b}.steps.s-commande i.d{background:#3b82f6}.steps.s-livraison i.d{background:#14b8a6}.steps.s-cloture i.d{background:#6b7280}
.badge.big{font-size:13px;padding:5px 12px}
.btn{display:inline-block;padding:9px 16px;border-radius:9px;font-size:14px;font-weight:600;text-decoration:none;border:0;cursor:pointer;font-family:inherit}
.bp{background:var(--p);color:var(--on)}.bs{background:#eef0f6;color:var(--t)}.bd{background:#b42318;color:#fff}
.cota{border:2px solid var(--p);background:var(--pl2)}
.big{font-size:26px;font-weight:700}
.act{display:flex;gap:10px;margin-top:12px;flex-wrap:wrap;align-items:center}
.priv{font-size:12px;color:var(--m);text-align:center;padding:16px 0 28px}
.alert{padding:12px 16px;border-radius:10px;margin:16px 0 0;font-size:14px}.al-s{background:#d1fae5;color:#065f46}.al-e{background:#fee2e2;color:#991b1b}
label{display:block;font-size:13px;font-weight:600;margin:12px 0 5px}
input[type=file]{width:100%;margin-top:4px;font-size:14px;font-family:inherit}
input[type=text],input[type=date],select,textarea{width:100%;padding:10px 12px;border:1px solid #d7dae0;border-radius:9px;font-size:15px;font-family:inherit;background:#fff}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--p);box-shadow:0 0 0 3px var(--pl)}
.err{color:#b42318;font-size:12px;margin-top:4px}
table.t{width:100%;border-collapse:collapse;font-size:14px}.t th{text-align:left;color:var(--m);font-weight:600;padding:8px 6px;border-bottom:1px solid var(--b)}.t td{padding:10px 6px;border-bottom:1px solid #f0f1f5}.t .n{text-align:right;white-space:nowrap}
details.d summary{list-style:none;cursor:pointer}details.d summary::-webkit-details-marker{display:none}
.hp{position:absolute;left:-9999px;height:0;overflow:hidden}
@media(max-width:600px){h1{font-size:20px}.who{text-align:left}.tabs{flex-wrap:wrap;gap:4px 16px;overflow:visible;white-space:normal}.tabs a{font-size:13.5px;padding:8px 2px}.row .btn{flex:0 0 auto}}
@media print{header.pt .who,.tabs,.act,.noprint,.priv{display:none!important}body{background:#fff}.card{border:0;padding:0}}
</style>
<style>.dl{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:10px 2px;border-bottom:1px solid #EEF1F5}.dl .nm{flex:1;min-width:180px}.dl .nm span.mut{display:block;font-size:12px}.dl .nm .nw{display:inline-block}</style>
<style>.top img{max-width:220px;object-fit:contain}.kp{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:14px 0 4px}.k{background:#fff;border:1px solid var(--b);border-radius:10px;padding:8px 12px}.k span{font-size:12px;color:var(--m);display:block}.k b{font-size:22px}.k.w{background:#FFF4DD;border-color:#F3D98B}.k.w span,.k.w b{color:#8A4B00}
.ban{display:flex;align-items:center;gap:10px 14px;background:#FFF4DD;border:1px solid #F3D98B;border-radius:10px;padding:10px 14px;margin-bottom:12px;flex-wrap:wrap;font-size:14px}.ban .bt{flex:1;min-width:220px}
.flt{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.flt input{flex:1;min-width:200px;width:auto}.flt select{width:auto;min-width:160px}
.pg{width:130px;flex:none}.pg i{display:block;height:5px;border-radius:3px;background:#e6e8ef;overflow:hidden}.pg u{display:block;height:100%;background:var(--p)}.pg small{display:block;font-size:11px;color:var(--m);margin-top:3px}
.so{display:inline-block;border-radius:6px;padding:1px 8px;font-size:11.5px;font-weight:600;margin-left:4px;background:var(--pl);color:var(--t)}
@media(max-width:600px){.kp{grid-template-columns:repeat(2,minmax(0,1fr))}.flt select{flex:1}.pg{width:100%}}</style>
